-- Four branch-specific researcher reports; La Cabra SoHo already exists and is not duplicated.
create or replace function public.import_field_reports() returns integer
language plpgsql security invoker set search_path='' as $$
declare entry jsonb; inserted integer:=0;
begin
 if auth.uid() is null then raise exception 'Researcher sign-in required'; end if;
 for entry in select value from jsonb_array_elements($reports$[{"city": "New York", "borough": "Manhattan", "neighborhood": "Roosevelt Island", "zip_code": "10044", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "Café@Cornell", "street_address": "2 West Loop Road", "latitude": 40.755686, "longitude": -73.956266, "category": "Café & bakery", "provider": "Unknown", "hardware": "Ingenico", "gateway": "FreedomPay", "verification_status": "Unverified", "notes": "Researcher reported: cafe@cornell — ingenico/freedompay. Ingenico is the terminal hardware and FreedomPay is the payment gateway; the underlying POS software was not identified. Observation date was not supplied. Address: Cornell Tech directory, https://tech.cornell.edu/contact/. Coordinates are an approximate address point from NYC Planning GeoSearch (nycpad 181837, confidence 0.8, fallback match); checkout/entrance position is not field-verified."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Roosevelt Island", "zip_code": "10044", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "Wholesome Factory", "street_address": "530 Main Street", "latitude": 40.760979, "longitude": -73.950442, "category": "Grocery & deli", "provider": "Clover", "hardware": "Unknown", "gateway": "Unknown", "verification_status": "Verified", "notes": "Researcher reported: wholesome on roosevelt island — clover. Clover is recorded as the reported POS provider. Terminal model, separate gateway, and observation date were not supplied. Address: Cornell dining directory, https://www.cs.cornell.edu/sites/default/files/shared/housing_banking_dining_at_tech.pdf. Coordinates are an approximate address point from NYC Planning GeoSearch (nycpad 181788, confidence 0.8, fallback match); checkout/entrance position is not field-verified."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Sutton Place", "zip_code": "10022", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "Trader Joe’s — Sutton Place", "street_address": "405 East 59th Street", "latitude": 40.759533, "longitude": -73.961325, "category": "Grocery & deli", "provider": "Unknown", "hardware": "Verifone", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Unverified", "notes": "Researcher reported: trader joe's sutton place: verifone. Verifone identifies terminal hardware; terminal model and POS software were not supplied. Observation date was not supplied. Address source: https://locations.traderjoes.com/ny/new-york/571/. Coordinates: NYC Planning GeoSearch nycpad 201170, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Roosevelt Island", "zip_code": "10044", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "Piccolo Trattoria Ristorante Pizzeria", "street_address": "455 Main Street", "latitude": 40.759268, "longitude": -73.952623, "category": "Restaurant", "provider": "Unknown", "hardware": "PAX S300", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Unverified", "notes": "Researcher reported: Piccolo Trattoria Ristorante Pizzeria roosevelt island: pax s300. PAX S300 is recorded as the reported terminal brand/model; POS software was not supplied. Observation date was not supplied. Address source: https://www.piccolotrattoriatistorantepizzeria.com/. Coordinates: NYC Planning GeoSearch nycpad 181933, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Upper East Side", "zip_code": "10065", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "il laboratorio del gelato — Upper East Side", "street_address": "1062 3rd Avenue", "latitude": 40.764049, "longitude": -73.965329, "category": "Café & bakery", "provider": "Square", "hardware": "Unknown", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Verified", "notes": "Researcher reported: labrotoria di gelato ues - squsre. Square is the researcher-reported POS provider. Hardware and gateway were not supplied. Spelling was normalized from the report. Observation date was not supplied. Address source: https://www.laboratoriodelgelato.com/. Coordinates: NYC Planning GeoSearch nycpad 185009, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Nolita", "zip_code": "10012", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "Gelateria Gentile — Nolita", "street_address": "229 Elizabeth Street", "latitude": 40.722918, "longitude": -73.9942, "category": "Café & bakery", "provider": "Toast", "hardware": "Unknown", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Verified", "notes": "Researcher reported: gelateria gentile - toast; branch subsequently confirmed as Nolita. Toast is the researcher-reported POS provider for the Nolita branch only. No claim is made about other branches. Observation date was not supplied. Address source: https://www.instagram.com/gelateria_gentile_ny/. Coordinates: NYC Planning GeoSearch nycpad 47480, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "SoHo", "zip_code": "10012", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "La Cabra — SoHo", "street_address": "284 Lafayette Street", "latitude": 40.72435, "longitude": -73.996281, "category": "Café & bakery", "provider": "Square", "hardware": "Unknown", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Verified", "notes": "Researcher reported: la cabra soho - square. Square is the researcher-reported POS provider for the SoHo branch only. Observation date was not supplied. Address source: https://lacabra.com/pages/soho. Coordinates: NYC Planning GeoSearch nycpad 47575, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Sutton Place", "zip_code": "10022", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "LaVista Pizza — 2nd Avenue", "street_address": "1099 2nd Avenue", "latitude": 40.75995, "longitude": -73.965159, "category": "Restaurant", "provider": "Unknown", "hardware": "Unknown", "payment_platform": "Valor PayTech", "gateway": "Unknown", "verification_status": "Unverified", "notes": "Researcher reported: la vista pizza ues - valor paytech. Valor PayTech is retained as a reported payment-platform brand. Its particular terminal model, gateway product and underlying POS software are not confirmed. The researcher described UES; the business lists its nearby East Side branch at 1099 2nd Avenue, matched here and grouped under Sutton Place. Observation date was not supplied. Address source: https://www.lavistapizza.com/contact. Coordinates: NYC Planning GeoSearch nycpad 175727, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Rose Hill", "zip_code": "10016", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "bb.q Chicken — Rose Hill", "street_address": "383 3rd Avenue", "latitude": 40.741528, "longitude": -73.980836, "category": "Restaurant", "provider": "Toast", "hardware": "Unknown", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Verified", "notes": "Researcher reported: bbq chicken rose hill - toast. Toast is the researcher-reported POS provider. Rose Hill is retained as the researcher's neighborhood label. Observation date was not supplied. Address source: https://order.bbqchicken.com/store/bb-q-chicken-3rd-ave-ny-23063686. Coordinates: NYC Planning GeoSearch nycpad 101427, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "neighborhood": "Roosevelt Island", "zip_code": "10044", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "Foodtown — Roosevelt Island", "street_address": "686 Main Street", "latitude": 40.76466, "longitude": -73.946705, "category": "Grocery & deli", "provider": "Unknown", "hardware": "Verifone", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Unverified", "notes": "Researcher reported: foodtown roosevelt island - verifone. Verifone identifies terminal hardware; terminal model and POS software were not supplied. Observation date was not supplied. Address source: https://www.fda.gov/media/153997/download. Coordinates: NYC Planning GeoSearch nycpad 181548, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Queens", "neighborhood": "Dutch Kills", "zip_code": "11106", "observation_date": "", "evidence_method": "Researcher-reported field observation", "business_name": "Il Miglio Brick Oven Pizza — Dutch Kills", "street_address": "11-03 36th Avenue", "latitude": 40.761156, "longitude": -73.939647, "category": "Restaurant", "provider": "Square", "hardware": "Unknown", "payment_platform": "Unknown", "gateway": "Unknown", "verification_status": "Verified", "notes": "Researcher reported: il moglio brick oven pizza in dutch kills - square. Name normalized to Il Miglio using the business website. Square is the researcher-reported POS provider for this location only. Terminal model, separate gateway, payment processor and observation date were not supplied. Address source: https://ilmigliomenu.com/. Coordinates: NYC Planning GeoSearch nycpad 1816666, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "observation_date": "", "evidence_method": "Researcher-reported field observation", "hardware": "PAX S300", "payment_platform": "Unknown", "gateway": "Unknown", "business_name": "Peng’s Noodle Folk — Upper East Side", "neighborhood": "Upper East Side", "street_address": "1016 Lexington Avenue", "zip_code": "10021", "latitude": 40.77099, "longitude": -73.962092, "category": "Restaurant", "provider": "Unknown", "verification_status": "Unverified", "notes": "Researcher reported: peng's noodle fork upper east side - pax s300; researcher subsequently confirmed the 1016 Lexington Avenue branch. Business name normalized to Peng’s Noodle Folk. PAX S300 is terminal hardware; POS software, gateway and payment processor were not identified. Observation date was not supplied. Address source: https://www.pengsnoodlefolk.com/about/. Coordinates: NYC Planning GeoSearch nycpad 186528, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "observation_date": "", "evidence_method": "Researcher-reported field observation", "hardware": "Verifone", "payment_platform": "Unknown", "gateway": "Unknown", "business_name": "Village Square Pizza — Upper East Side", "neighborhood": "Upper East Side", "street_address": "1200 Lexington Avenue", "zip_code": "10028", "latitude": 40.776594, "longitude": -73.957947, "category": "Restaurant", "provider": "Lightspeed", "verification_status": "Verified", "notes": "Researcher reported: village square pizza ues - lightspeed on a verifone hardware. Lightspeed is recorded as the reported POS software and Verifone as terminal hardware. Terminal model, gateway and payment processor were not supplied. Branch-specific report only. Observation date was not supplied. Address source: https://villagesquarepizzanyc.com/pages/contact. Coordinates: NYC Planning GeoSearch nycpad 207603, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "observation_date": "", "evidence_method": "Researcher-reported field observation", "hardware": "Unknown", "payment_platform": "Unknown", "gateway": "Unknown", "business_name": "Stüssy — SoHo", "neighborhood": "SoHo", "street_address": "50 Prince Street", "zip_code": "10012", "latitude": 40.723275, "longitude": -73.996038, "category": "Retail", "provider": "Shopify POS", "verification_status": "Verified", "notes": "Researcher reported: stussy soho - shopify. Shopify is normalized to the controlled Shopify POS label for the reported in-store POS identification. Hardware, gateway and payment processor were not supplied. No inference is made from the online storefront. Observation date was not supplied. Address source: https://www.stussy.com/blogs/chapters/stussy-new-york. Coordinates: NYC Planning GeoSearch nycpad 46299, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}, {"city": "New York", "borough": "Manhattan", "observation_date": "", "evidence_method": "Researcher-reported field observation", "hardware": "Verifone", "payment_platform": "Adyen", "gateway": "Unknown", "business_name": "Charles Tyrwhitt — Times Square", "neighborhood": "Times Square", "street_address": "745 Seventh Avenue", "zip_code": "10036", "latitude": 40.760565, "longitude": -73.982934, "category": "Retail", "provider": "Unknown", "verification_status": "Unverified", "notes": "Researcher reported: charles thyrwitt times square - adyen on verifone hardware. Business spelling normalized to Charles Tyrwhitt. Adyen is retained as the reported payment-platform/processor brand and Verifone as terminal hardware. This does not establish the merchant’s POS software, gateway product or terminal model. Branch-specific report only. Observation date was not supplied. Address source: https://www.timessquarenyc.org/retail/charles-tyrwhitt. Coordinates: NYC Planning GeoSearch nycpad 111860, confidence 0.8, fallback match. Approximate address/building point, not a field-verified entrance or checkout."}]$reports$::jsonb) loop
  if not exists(select 1 from public.merchants where owner_id=auth.uid() and lower(trim(business_name))=lower(trim(entry->>'business_name')) and lower(trim(street_address))=lower(trim(entry->>'street_address')) and zip_code=entry->>'zip_code') then
   perform public.save_merchant_observation(entry);
   inserted:=inserted+1;
  end if;
 end loop;
 return inserted;
end $$;
revoke all on function public.import_field_reports() from public,anon;
grant execute on function public.import_field_reports() to authenticated;
